static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 从输入形状获取 M, K, N
    const auto *x_shape = context->GetInputShape(0); // [M, K]
    const auto *w_shape = context->GetInputShape(1); // 传入为 [K, N]（在Python侧已转置并contiguous）
