    uint64_t K = static_cast<uint64_t>(x_shape->GetOriginShape().GetDim(1));
    uint64_t K2 = static_cast<uint64_t>(w_shape->GetOriginShape().GetDim(0));
    uint64_t N = static_cast<uint64_t>(w_shape->GetOriginShape().GetDim(1));
    if (K != K2) {
        return ge::GRAPH_PARAM_INVALID;
    }

    // 配置Matmul NORMAL布局，单批
    constexpr bool aTranspose = false;
    constexpr bool bTranspose = false; // 我们传入的是[K, N]，无需在内核再转置
