    // 让框架计算并下发TCubeTiling到RawTilingData
    // 这里使用框架提供的接口将tiling直接保存到RawTilingData
    auto *raw = context->GetRawTilingData();
    uint8_t *buf = raw->GetData();
    uint32_t cap = raw->GetCapacity();

    matmul::MatmulApiTilingInput tilingIn;
    tilingIn.m = static_cast<uint32_t>(M);
    tilingIn.n = static_cast<uint32_t>(N);
    tilingIn.k = static_cast<uint32_t>(K);
    tilingIn.isTransA = aTranspose;
    tilingIn.isTransB = bTranspose;
    tilingIn.layout = matmul::LayoutMode::NORMAL;
    tilingIn.aType = ge::DT_FLOAT;
    tilingIn.bType = ge::DT_FLOAT;
    tilingIn.cType = ge::DT_FLOAT;
    tilingIn.withBias = true;

    matmul::GetMatmulApiTiling(MM_CFG, tilingIn, buf, cap);

    // 设置BlockDim和Workspace
    context->SetBlockDim(8);
    raw->SetDataSize(raw->GetCapacity()); // 直接占满（由框架填充的实际大小会设置）
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
